from pathlib import Path
files={}
files['src/components/common/OperationalTaskCard.jsx']=r'''import {Link} from 'react-router-dom';
import {Clock3,ArrowRight,Building2} from 'lucide-react';
import {Card,CardContent,Status,Button} from '@/components/manager/ManagerUI';
export default function OperationalTaskCard({task,facility,to}){return <Card className="staff-task-card"><CardContent><div className="flex flex-wrap items-center justify-between gap-3"><span className="text-xs font-bold text-[#176B3A]">{task.type.replaceAll('_',' ')}</span><Status value={task.priority}/></div><h3 className="mt-4 text-lg font-bold">{task.title}</h3><p className="mt-2 text-xs text-slate-500">{task.id}</p><div className="my-4 flex flex-wrap gap-3 text-xs text-slate-500"><span className="flex items-center gap-1"><Clock3 size={14}/>{task.date} · {task.time}</span><span className="flex items-center gap-1"><Building2 size={14}/>{facility}</span></div><div className="flex flex-wrap items-center justify-between gap-3"><Status value={task.status}/><Button asChild size="sm" className="staff-action"><Link to={to}>Open task<ArrowRight size={15}/></Link></Button></div></CardContent></Card>;}
'''
files['src/components/common/ItemLocationDisplay.jsx']=r'''import {MapPin} from 'lucide-react';
export default function ItemLocationDisplay({value,label='Current location'}){return <div className="rounded-xl border border-[#dce7de] bg-[#f1f6ef] p-4"><p className="flex items-center gap-2 text-xs font-semibold text-[#526554]"><MapPin size={15}/>{label}</p>{value?<div className="mt-3 flex flex-wrap items-center gap-2 text-sm font-bold"><span>{value.zone}</span><span className="text-[#9aa99d]">/</span><span>{value.rack}</span><span className="text-[#9aa99d]">/</span><span>{value.shelf}</span></div>:<p className="mt-3 text-sm font-semibold">No current location</p>}</div>;}
'''
files['src/components/staff/StaffUI.jsx']=r'''import {useRef,useState} from 'react';
import {Checkbox} from '@/components/ui/checkbox';
import {Screen,NotFound,Dialog,Button,Message,Status,Details} from '@/components/manager/ManagerUI';
import {staffDemoEnabled,rentalFor,customer} from '@/lib/staffDemoStore';
import {staffFacility} from '@/mocks/staffData';
export function StaffScreen(props){return <Screen {...props} notice={staffDemoEnabled?'Staff demo · Only the selected demo operator’s assigned tasks are actionable. Changes stay in this browser; no real access, item handling, transfers or backend operations are performed.':'Staff operational APIs are not connected · No demo data or operational writes are enabled in live mode.'}/>;}
export function StaffUnavailable({title}){return <NotFound title={title||'Assigned record unavailable'} to="/staff/dashboard"/>;}
export function Checklist({labels,values,onChange,disabled=false}){return <div className="space-y-4">{labels.map((label,i)=><label key={label} className="flex items-start gap-3 text-sm leading-6"><Checkbox aria-label={label} checked={values[i]===true} disabled={disabled} onCheckedChange={value=>onChange(values.map((v,j)=>j===i?value===true:v))}/><span>{label}</span></label>)}</div>;}
export function ConfirmAction({label,title,disabled,summary,run,onSuccess}){const [open,setOpen]=useState(false),[error,setError]=useState(''),[success,setSuccess]=useState(''),busy=useRef(false);function confirm(){if(busy.current)return;busy.current=true;try{run();setOpen(false);setSuccess('Confirmed in the Staff demo workspace.');onSuccess?.();}catch(err){setError(err.message);}finally{busy.current=false;}}return <div className="space-y-4"><Message success={success}/><Button type="button" className="staff-action h-12" variant="orange" disabled={disabled||!staffDemoEnabled} onClick={()=>{setError('');setOpen(true);}}>{label}</Button>{open&&<Dialog title={title||label} onClose={()=>setOpen(false)}><p className="mb-4 text-sm text-slate-500">Review this local demo operation before confirming. No backend request will be made.</p>{summary}<Message error={error}/><div className="mt-5 flex flex-wrap gap-3"><Button type="button" variant="orange" className="h-12" onClick={confirm}>Confirm demo operation</Button><Button type="button" variant="outline" className="h-12" onClick={()=>setOpen(false)}>Cancel</Button></div></Dialog>}</div>;}
export function TaskContext({data,task}){const rental=rentalFor(data,task),client=customer(data,rental?.customerId),unit=data.units.find(u=>u.id===rental?.unitId),payment=data.payments.find(p=>p.id===rental?.paymentId);return <Details values={[["Task",task.id],['Priority',<Status value={task.priority}/>],['Due',`${task.date} · ${task.time}`],['Facility',staffFacility.name],['Status',<Status value={task.status}/>],['Customer',client?.name||'—'],['Rental',rental?.id||'—'],['Rental status',rental?<Status value={rental.status}/>:'—'],['Service',rental?.service.replaceAll('_',' ')||'Facility operation'],...(rental?.service==='SELF_STORAGE'?[['Exact reserved unit',unit?.code||'Unavailable'],['Unit size',unit?.size||'—'],['Payment status',payment?.status||'—'],['Payment reference',payment?.reference||'—']]:rental?[['Allocated capacity',`${rental.allocated_capacity_m3} m³`],['Used capacity',`${rental.used_capacity_m3} m³`]]:[])]}/>;}
export const taskClosed=task=>['COMPLETED','CANCELLED'].includes(task.status);
'''
files['src/layouts/StaffLayout.jsx']=r'''import {Link,NavLink,Outlet} from 'react-router-dom';
import {LayoutDashboard,ClipboardList,LogIn,LogOut,ClipboardCheck,KeyRound,PackagePlus,PackageCheck,Move,History,LifeBuoy,Wrench,Wallet,Building2} from 'lucide-react';
import Brand from '@/components/common/Brand';
import LogoutButton from '@/components/common/LogoutButton';
import {Select} from '@/components/manager/ManagerUI';
import {useAuthSession} from '@/lib/authSession';
import {useStaffData,selectDemoOperator,staffDemoEnabled,operator} from '@/lib/staffDemoStore';
import {staffFacility,staffOperators} from '@/mocks/staffData';
import './experience.css';import './manager.css';import './staff.css';
const links=[['dashboard',LayoutDashboard,'Dashboard'],['tasks',ClipboardList,'My tasks'],['check-ins',LogIn,'Check-in'],['handovers',KeyRound,'Handover'],['inspections',ClipboardCheck,'Inspection'],['checkouts',LogOut,'Checkout'],['inventory/inbound',PackagePlus,'Inventory inbound'],['inventory/relocation',Move,'Relocation'],['inventory/outbound',PackageCheck,'Inventory outbound'],['inventory/history',History,'Movement history'],['support',LifeBuoy,'Support'],['maintenance',Wrench,'Maintenance'],['refunds',Wallet,'Refund processing']];
export default function StaffLayout(){const data=useStaffData(),{user}=useAuthSession(),staff=operator(data);return <div className="experience-theme manager-shell staff-shell"><header className="manager-topbar"><Link to="/staff/dashboard" aria-label="VaultSpace Staff"><Brand/></Link><div className="staff-operator"><span className="text-[10px] font-bold uppercase tracking-wider text-[#6b7e70]">Demo operator</span><Select label="Demo operator" value={data.operatorId||''} onChange={selectDemoOperator} options={staffDemoEnabled?staffOperators.map(row=>[row.id,`${row.name} · ${row.role}`]):[["","Operational API unavailable"]]} disabled={!staffDemoEnabled}/></div><div className="manager-identity"><span className="manager-avatar">ST</span><span><b>{user?.displayName||staff?.name||'Staff workspace'}</b><small>Facility Staff</small></span><LogoutButton compact/></div></header><div className="manager-workspace"><aside className="manager-sidebar"><p className="px-3 pb-3 text-[10px] font-bold uppercase tracking-widest text-[#7a8b7f]">Assigned operations</p><nav aria-label="Staff navigation">{links.map(([path,Icon,label])=><NavLink key={path} to={`/staff/${path}`}><Icon size={17}/>{label}</NavLink>)}</nav><div className="manager-scope"><Building2 size={18}/><p>{staffFacility.name}<br/><b>{staffDemoEnabled?'Assigned demo facility':'Operational API pending'}</b></p><span>{staffFacility.id} · {staff?.role||'No operational assignment'}</span></div></aside><main className="manager-main"><Outlet/></main></div></div>;}
'''
files['src/layouts/staff.css']=r'''/* Staff-only additions reuse Manager tables, forms, cards and responsive layout. */
.staff-operator{display:flex;align-items:center;gap:12px}.staff-operator select{width:280px;height:44px}.staff-action{min-height:48px;padding-left:20px;padding-right:20px}.staff-task-card{transition:border-color .15s,box-shadow .15s}.staff-task-card:hover{border-color:#b6d5be;box-shadow:0 8px 24px #176b3a10}.staff-summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.staff-summary{padding:22px;border:1px solid #e1e8e2;border-radius:16px;background:white}.staff-summary b{display:block;font-size:30px;margin-top:10px}.staff-summary .staff-summary-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;background:#eaf5ee;color:#176b3a}.staff-summary:nth-child(2n) .staff-summary-icon{color:#db7919;background:#fff1e3}.staff-blockers{border:1px solid #f4d9b9;background:#fff8ef;padding:18px;border-radius:12px;font-size:13px;line-height:1.8}.staff-complete{border:1px solid #c6dfcc;background:#eaf5ee;padding:18px;border-radius:12px;font-size:13px;line-height:1.8}.staff-location-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.staff-measurement-compare{font-size:12px;line-height:1.7;padding:14px;border-radius:10px;background:#f1f6ef}.staff-shell .manager-demo{line-height:1.8}.staff-shell .manager-avatar{flex-shrink:0}.staff-shell [role=checkbox]{flex-shrink:0;margin-top:3px}.staff-shell .manager-identity>span:last-of-type{max-width:200px;overflow-wrap:anywhere}.staff-shell .staff-task-card h3{overflow-wrap:anywhere}
@media(max-width:1100px){.staff-summary-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.staff-operator>span{display:none}.staff-operator select{width:235px}}
@media(max-width:760px){.staff-shell .manager-topbar{flex-wrap:wrap;height:126px;gap:10px;padding-top:12px;padding-bottom:10px}.staff-shell .manager-identity>span:not(.manager-avatar){display:none}.staff-operator{order:3;width:100%}.staff-operator select{width:100%;height:36px}.staff-shell .manager-sidebar{top:126px}.staff-location-grid{grid-template-columns:1fr}.staff-summary-grid{gap:10px}.staff-summary{padding:16px}.staff-summary .text-sm{font-size:12px}.staff-summary b{font-size:26px}.staff-shell .manager-screen{padding-top:24px}.staff-shell .staff-task-card [class*=p-6]{padding:20px}}
'''
