p=Path('src/components/manager/ManagerUI.jsx');s=p.read_text(encoding='utf-8');s=s.replace('code,action,children}', 'code,action,notice,children}');s=s.replace("{managerDemoEnabled?'Demo facility", "{notice??(managerDemoEnabled?'Demo facility");s=s.replace("Live data and actions are unavailable.'}</p>", "Live data and actions are unavailable.')}</p>");s=s.replace("'IN_STORAGE'].includes(value)", "'IN_STORAGE','Paid','Active','Closed','InStorage','CheckedOut','PASSED'].includes(value)");s=s.replace("NotFound({title='Record unavailable'})", "NotFound({title='Record unavailable',to='/manager/dashboard'})");s=s.replace('<OpenLink to="/manager/dashboard">Back to dashboard</OpenLink>', '<OpenLink to={to}>Back to dashboard</OpenLink>');p.write_text(s,encoding='utf-8')
